const double PI = 3.14159265358979323846;
// Synthizer ran at a fixed 44100hz; its sample based constants are scaled from this rate.
const double REFERENCE_SR = 44100.0;
// Parameters are polled and HRTF input is buffered in chunks of at most this many frames.
const unsigned int CHUNK = 256;

template <class T> T clamp(T v, T lo, T hi) { return v < lo ? lo : v > hi ? hi : v; }
inline double sanitize(double v, double lo, double hi) { return std::isnan(v) ? lo : clamp(v, lo, hi); }
inline double db_to_gain(double db) { return std::pow(10.0, db / 20.0); }
inline double wrap_azimuth(double azimuth) {
	if (!std::isfinite(azimuth)) return 0.0;
	azimuth = std::fmod(azimuth, 360.0);
	return azimuth < 0.0 ? azimuth + 360.0 : azimuth;
}
inline unsigned int scale_samples(unsigned int sr, double samples_at_reference) { return std::max(1u, (unsigned int)std::lround(samples_at_reference * sr / REFERENCE_SR)); }
inline unsigned int next_pow2(unsigned int v) {
	unsigned int r = 1;
	while (r < v) r <<= 1;
	return r;
}

// Flushes denormals to zero while processing; decaying feedback loops otherwise spend most of their time in denormal arithmetic.
class denormal_guard {
#ifdef MICROSYNTHISER_SSE
	unsigned int csr;

public:
	denormal_guard() : csr(_mm_getcsr()) { _mm_setcsr(csr | 0x8040); }
	~denormal_guard() { _mm_setcsr(csr); }
#endif
};

// Holds parameters written by any thread. The audio thread only ever try_locks, so a setter can delay a parameter change by one call but never block audio.
template <class T> class param_box {
	mutable std::mutex mutex;
	T pending;
	std::atomic<bool> dirty{false};

public:
	template <class F> void write(F &&f) {
		std::lock_guard<std::mutex> lock(mutex);
		f(pending);
		dirty.store(true, std::memory_order_release);
	}
	T read() const {
		std::lock_guard<std::mutex> lock(mutex);
		return pending;
	}
	bool poll(T &out) {
		if (!dirty.load(std::memory_order_acquire)) return false;
		std::unique_lock<std::mutex> lock(mutex, std::try_to_lock);
		if (!lock.owns_lock()) return false;
		out = pending;
		dirty.store(false, std::memory_order_relaxed);
		return true;
	}
};

struct ramp {
	float value = 0.0f, target = 0.0f, step = 0.0f;
	unsigned int remaining = 0;
	void snap(float v) {
		value = target = v;
		remaining = 0;
	}
	void set(float t, unsigned int length) {
		if (t == target) return;
		target = t;
		remaining = length;
		step = (target - value) / length;
	}
	float next() {
		if (!remaining) return value;
		value = --remaining ? value + step : target;
		return value;
	}
};

// Moves a delay length to a new value along a smoothstep curve, so that changing it produces a short pitch glide instead of a click.
struct glide {
	double from = 0.0, to = 0.0, value = 0.0;
	unsigned int pos = 1, length = 1;
	void snap(double v) {
		from = to = value = v;
		pos = length;
	}
	void set(double v, unsigned int len) {
		if (v == to) return;
		from = value;
		to = v;
		length = std::max(1u, len);
		pos = 0;
	}
	bool active() const { return pos < length; }
	double next() {
		if (pos >= length) return value;
		double t = double(++pos) / length;
		value = pos == length ? to : from + (to - from) * t * t * (3.0 - 2.0 * t);
		return value;
	}
};

// xoshiro256++ by David Blackman and Sebastiano Vigna (public domain), seeded through splitmix64 from a global counter so that every instance gets a different sequence.
class rng {
	std::uint64_t s[4];
	static std::uint64_t rotl(std::uint64_t x, int k) { return (x << k) | (x >> (64 - k)); }

public:
	rng() {
		static std::atomic<std::uint64_t> counter{0};
		std::uint64_t z = counter.fetch_add(1, std::memory_order_relaxed) * 0x632BE59BD9B4E019ull;
		for (auto &v : s) {
			std::uint64_t x = (z += 0x9E3779B97F4A7C15ull);
			x = (x ^ (x >> 30)) * 0xBF58476D1CE4E5B9ull;
			x = (x ^ (x >> 27)) * 0x94D049BB133111EBull;
			v = x ^ (x >> 31);
		}
	}
	std::uint64_t next() {
		const std::uint64_t result = rotl(s[0] + s[3], 23) + s[0], t = s[1] << 17;
		s[2] ^= s[0];
		s[3] ^= s[1];
		s[1] ^= s[2];
		s[0] ^= s[3];
		s[2] ^= t;
		s[3] = rotl(s[3], 45);
		return result;
	}
	// Uniform in [-1, 1).
	float next_float() { return float(next() >> 40) * (2.0f / 16777216.0f) - 1.0f; }
};

// Synthizer's InterpolatedRandomSequence: wanders between random values in a range, picking a new one every steps samples. It interpolates with smoothstep rather than linearly so that the pitch of a modulated delay line has no jumps at the breakpoints.
class random_sequence {
	rng gen;
	float range_min = 0.0f, range_size = 0.0f, last = 0.0f, target = 0.0f, value = 0.0f, inv_steps = 1.0f;
	unsigned int steps = 1, countdown = 1;

public:
	// Starts moving from the current value into the new range, like Synthizer's reconstruct-with-the-last-tick pattern.
	void configure(unsigned int step_count, float min_value, float max_value) {
		steps = std::max(1u, step_count);
		inv_steps = 1.0f / steps;
		range_min = min_value;
		range_size = max_value - min_value;
		last = target = value;
		countdown = 1;
	}
	float tick() {
		float t = (steps - countdown) * inv_steps;
		value = last + (target - last) * t * t * (3.0f - 2.0f * t);
		if (!--countdown) {
			last = target;
			target = range_min + range_size * (gen.next_float() + 1.0f) * 0.5f;
			countdown = steps;
		}
		return value;
	}
};

class prime_table {
	std::vector<bool> composite;

public:
	explicit prime_table(unsigned int limit) : composite(limit + 1, false) {
		composite[0] = composite[1] = true;
		for (unsigned int i = 2; i * i <= limit; i++)
			if (!composite[i])
				for (unsigned int j = i * i; j <= limit; j += i) composite[j] = true;
	}
	// The prime closest to input which isn't in the exclusion list; on ties the larger wins, as in Synthizer.
	unsigned int closest(unsigned int input, const unsigned int *exclude, unsigned int exclude_count) const {
		const unsigned int size = (unsigned int)composite.size();
		input = std::min(input, size - 1);
		auto usable = [&](unsigned int v) { return !composite[v] && std::find(exclude, exclude + exclude_count, v) == exclude + exclude_count; };
		unsigned int lower = input, upper = input + 1;
		while (lower >= 2 && !usable(lower)) lower--;
		while (upper < size && !usable(upper)) upper++;
		bool has_lower = lower >= 2, has_upper = upper < size;
		if (has_lower && (!has_upper || input - lower < upper - input)) return lower;
		return has_upper ? upper : 2;
	}
};

// An orthonormal 8 point Hadamard transform.
inline void hadamard8(float *v) {
	for (unsigned int h = 1; h < 8; h <<= 1)
		for (unsigned int i = 0; i < 8; i += h * 2)
			for (unsigned int j = i; j < i + h; j++) {
				float a = v[j], b = v[j + h];
				v[j] = a + b;
				v[j + h] = a - b;
			}
	for (unsigned int i = 0; i < 8; i++) v[i] *= 0.35355339059327373f;
}

// Coefficients are normalized so that a0 is 1.
struct biquad_coefs {
	double b0 = 1.0, b1 = 0.0, b2 = 0.0, a1 = 0.0, a2 = 0.0;
};

// Direct form 1 in double precision, which tolerates coefficient changes on a running signal better than Synthizer's direct form 2.
struct biquad_state {
	double x1 = 0.0, x2 = 0.0, y1 = 0.0, y2 = 0.0;
	double tick(const biquad_coefs &c, double x) {
		double y = c.b0 * x + c.b1 * x1 + c.b2 * x2 - c.a1 * y1 - c.a2 * y2;
		x2 = x1;
		x1 = x;
		y2 = y1;
		y1 = y;
		return y;
	}
};

// The Audio EQ Cookbook. Shelves use q rather than slope; q = sqrt(1/2) is the same as Synthizer's slope of 1.
inline biquad_coefs design_biquad(biquad_type type, double frequency, double q, double gain_db, unsigned int sr) {
	biquad_coefs c;
	if (type == biquad_type::none) return c;
	const double w0 = 2.0 * PI * clamp(frequency / sr, 1e-5, 0.4999), cw = std::cos(w0), sw = std::sin(w0);
	const double alpha = sw / (2.0 * std::max(q, 1e-3)), a = std::pow(10.0, gain_db / 40.0), sa = 2.0 * std::sqrt(a) * alpha;
	double b0 = 1.0, b1 = 0.0, b2 = 0.0, a0 = 1.0, a1 = 0.0, a2 = 0.0;
	switch (type) {
	case biquad_type::lowpass:
		b0 = b2 = (1.0 - cw) / 2.0;
		b1 = 1.0 - cw;
		a0 = 1.0 + alpha, a1 = -2.0 * cw, a2 = 1.0 - alpha;
		break;
	case biquad_type::highpass:
		b0 = b2 = (1.0 + cw) / 2.0;
		b1 = -(1.0 + cw);
		a0 = 1.0 + alpha, a1 = -2.0 * cw, a2 = 1.0 - alpha;
		break;
	case biquad_type::bandpass:
		b0 = alpha, b1 = 0.0, b2 = -alpha;
		a0 = 1.0 + alpha, a1 = -2.0 * cw, a2 = 1.0 - alpha;
		break;
	case biquad_type::notch:
		b0 = 1.0, b1 = -2.0 * cw, b2 = 1.0;
		a0 = 1.0 + alpha, a1 = -2.0 * cw, a2 = 1.0 - alpha;
		break;
	case biquad_type::allpass:
		b0 = 1.0 - alpha, b1 = -2.0 * cw, b2 = 1.0 + alpha;
		a0 = 1.0 + alpha, a1 = -2.0 * cw, a2 = 1.0 - alpha;
		break;
	case biquad_type::peaking:
		b0 = 1.0 + alpha * a, b1 = -2.0 * cw, b2 = 1.0 - alpha * a;
		a0 = 1.0 + alpha / a, a1 = -2.0 * cw, a2 = 1.0 - alpha / a;
		break;
	case biquad_type::lowshelf:
		b0 = a * ((a + 1.0) - (a - 1.0) * cw + sa), b1 = 2.0 * a * ((a - 1.0) - (a + 1.0) * cw), b2 = a * ((a + 1.0) - (a - 1.0) * cw - sa);
		a0 = (a + 1.0) + (a - 1.0) * cw + sa, a1 = -2.0 * ((a - 1.0) + (a + 1.0) * cw), a2 = (a + 1.0) + (a - 1.0) * cw - sa;
		break;
	case biquad_type::highshelf:
		b0 = a * ((a + 1.0) + (a - 1.0) * cw + sa), b1 = -2.0 * a * ((a - 1.0) + (a + 1.0) * cw), b2 = a * ((a + 1.0) + (a - 1.0) * cw - sa);
		a0 = (a + 1.0) - (a - 1.0) * cw + sa, a1 = 2.0 * ((a - 1.0) - (a + 1.0) * cw), a2 = (a + 1.0) - (a - 1.0) * cw - sa;
		break;
	default:
		break;
	}
	c.b0 = b0 / a0, c.b1 = b1 / a0, c.b2 = b2 / a0, c.a1 = a1 / a0, c.a2 = a2 / a0;
	return c;
}

// Synthizer's channel mixing rules for getting to and from the stereo used internally: mono is duplicated/averaged, extra channels are dropped or left dry.
inline void read_stereo(const float *frame, unsigned int channels, float &l, float &r) {
	l = frame[0];
	r = channels > 1 ? frame[1] : frame[0];
}

inline void write_stereo(const float *in, float *out, unsigned int channels, float l, float r, float dry, bool accumulate) {
	for (unsigned int c = 0; c < channels; c++) {
		float v = in[c] * dry + (channels == 1 ? (l + r) * 0.5f : c == 0 ? l : c == 1 ? r : 0.0f);
		out[c] = accumulate ? out[c] + v : v;
	}
}

/* HRTF. Angles here are in degrees following the dataset's conventions: azimuth clockwise from forward and elevation from -90 to 90. The dataset is for the left ear; the right ear uses the mirrored azimuth. */

const unsigned int HRTF_ELEVATION_COUNT = 14, HRTF_IMPULSE_COUNT = 710, HRTF_IMPULSE_LENGTH = 32;
// Maximum interaural time difference in samples at 44100hz, from the Woodworth formula's maximum for a 0.15m radius rounded up to a power of 2.
const double HRTF_MAX_ITD = 64.0;
const double HEAD_RADIUS = 0.08, SPEED_OF_SOUND = 343.0;

struct hrtf_elevation {
	double angle;
	unsigned int start, count;
};

extern const hrtf_elevation hrtf_elevations[HRTF_ELEVATION_COUNT];
extern const float hrtf_impulses[HRTF_IMPULSE_COUNT][HRTF_IMPULSE_LENGTH];

// The impulses resampled to one sample rate. length is padded to a multiple of 4 for SIMD.
struct hrtf_dataset {
	unsigned int sr = 0, length = 0;
	std::vector<float> impulses;
};

/* The dataset is recorded at 44100hz. Other rates get a band limited (Blackman windowed sinc) resampling of every impulse. Scaling by the rate ratio keeps the frequency response, rather than the sum of the taps, the same. Results are cached and shared between all instances. */
inline std::shared_ptr<const hrtf_dataset> get_hrtf_dataset(unsigned int sr) {
	static std::mutex mutex;
	static std::vector<std::shared_ptr<const hrtf_dataset>> cache;
	std::lock_guard<std::mutex> lock(mutex);
	for (auto &d : cache)
		if (d->sr == sr) return d;
	auto data = std::make_shared<hrtf_dataset>();
	data->sr = sr;
	// The kernel extends radius input samples either side of each tap; starting the output that far early keeps the ringing ahead of the dataset's large first tap, at the cost of well under a millisecond of latency.
	const double ratio = REFERENCE_SR / sr, cutoff = std::min(1.0, 1.0 / ratio), radius = 6.0 / cutoff;
	data->length = (unsigned int)std::ceil((HRTF_IMPULSE_LENGTH + 2.0 * radius) / ratio);
	data->length = (data->length + 3) & ~3u;
	data->impulses.assign(HRTF_IMPULSE_COUNT * data->length, 0.0f);
	for (unsigned int i = 0; i < HRTF_IMPULSE_COUNT; i++) {
		float *out = &data->impulses[i * data->length];
		if (sr == (unsigned int)REFERENCE_SR) {
			std::copy(hrtf_impulses[i], hrtf_impulses[i] + HRTF_IMPULSE_LENGTH, out);
			continue;
		}
		for (unsigned int n = 0; n < data->length; n++) {
			double t = n * ratio - radius, sum = 0.0;
			for (unsigned int k = 0; k < HRTF_IMPULSE_LENGTH; k++) {
				double x = t - k;
				if (std::fabs(x) >= radius) continue;
				double sinc = x == 0.0 ? 1.0 : std::sin(PI * cutoff * x) / (PI * cutoff * x), u = x / radius;
				sum += hrtf_impulses[i][k] * cutoff * sinc * (0.42 + 0.5 * std::cos(PI * u) + 0.08 * std::cos(2.0 * PI * u));
			}
			out[n] = float(sum * ratio);
		}
	}
	cache.push_back(data);
	return data;
}

// Returns {left, right} weights for linear interpolation of val between start and end.
inline std::pair<double, double> linear_weights(double val, double start, double end) {
	if (start == end) return {1.0, 0.0};
	double w = (clamp(val, start, end) - start) / (end - start);
	return {1.0 - w, w};
}

// Bilinear interpolation over azimuth and elevation. This works because the dataset is minimum phase.
inline void hrtf_single_channel(const hrtf_dataset &data, double azimuth, double elevation, const hrtf_elevation *lower, const hrtf_elevation *upper, float *out) {
	const hrtf_elevation *elevs[2] = {lower, upper};
	double elev_weights[2] = {1.0, 0.0};
	if (lower != upper) std::tie(elev_weights[0], elev_weights[1]) = linear_weights(elevation, lower->angle, upper->angle);
	std::fill(out, out + data.length, 0.0f);
	for (unsigned int e = 0; e < (lower != upper ? 2u : 1u); e++) {
		const hrtf_elevation *el = elevs[e];
		const double step = 360.0 / el->count;
		unsigned int i = (unsigned int)(azimuth / step), i1 = i % el->count, i2 = (i1 + 1) % el->count;
		auto w = i1 == i2 ? std::make_pair(1.0, 0.0) : linear_weights(azimuth, i * step, (i + 1) * step);
		const float *a = &data.impulses[(el->start + i1) * data.length], *b = &data.impulses[(el->start + i2) * data.length];
		float wa = float(w.first * elev_weights[e]), wb = float(w.second * elev_weights[e]);
		for (unsigned int k = 0; k < data.length; k++) out[k] += a[k] * wa + b[k] * wb;
	}
}

inline void compute_hrtf_impulses(const hrtf_dataset &data, double azimuth, double elevation, float *left, float *right) {
	const hrtf_elevation *lower = nullptr, *upper = nullptr;
	for (auto &e : hrtf_elevations) {
		if (e.angle <= elevation) lower = &e;
		else {
			upper = &e;
			break;
		}
	}
	lower = lower ? lower : upper;
	upper = upper ? upper : lower;
	// The dataset doesn't cover the whole sphere; elevations below the lowest recorded one use it.
	elevation = clamp(elevation, lower->angle, upper->angle);
	hrtf_single_channel(data, azimuth, elevation, lower, upper, left);
	hrtf_single_channel(data, 360.0 - azimuth, elevation, lower, upper, right);
}

// The Woodworth formula. Returns delays in fractional samples for {left, right}; one is always 0.
inline std::pair<double, double> compute_itd(double azimuth, double elevation, unsigned int sr) {
	double az = azimuth * PI / 180.0, el = elevation * PI / 180.0;
	// The lateral angle, folded into the front right quadrant since the head is front/back symmetric.
	double angle = PI / 2.0 - std::acos(std::fabs(std::sin(az) * std::cos(el)));
	double itd = std::min((HEAD_RADIUS / SPEED_OF_SOUND) * (angle + std::sin(angle)) * sr, HRTF_MAX_ITD * sr / REFERENCE_SR);
	// A source on the left delays the right ear.
	return (unsigned int)(az / PI) % 2 ? std::make_pair(0.0, itd) : std::make_pair(itd, 0.0);
}

inline void convolve_stereo(const float *x, const float *hl, const float *hr, unsigned int length, float &l, float &r) {
#ifdef MICROSYNTHISER_SSE
	__m128 al = _mm_setzero_ps(), ar = _mm_setzero_ps();
	for (unsigned int i = 0; i < length; i += 4) {
		__m128 s = _mm_loadu_ps(x + i);
		al = _mm_add_ps(al, _mm_mul_ps(s, _mm_loadu_ps(hl + i)));
		ar = _mm_add_ps(ar, _mm_mul_ps(s, _mm_loadu_ps(hr + i)));
	}
	auto hsum = [](__m128 v) {
		v = _mm_add_ps(v, _mm_shuffle_ps(v, v, _MM_SHUFFLE(1, 0, 3, 2)));
		return _mm_cvtss_f32(_mm_add_ps(v, _mm_shuffle_ps(v, v, _MM_SHUFFLE(2, 3, 0, 1))));
	};
	l = hsum(al);
	r = hsum(ar);
#else
	float l0 = 0.0f, l1 = 0.0f, l2 = 0.0f, l3 = 0.0f, r0 = 0.0f, r1 = 0.0f, r2 = 0.0f, r3 = 0.0f;
	for (unsigned int i = 0; i < length; i += 4) {
		l0 += x[i] * hl[i], l1 += x[i + 1] * hl[i + 1], l2 += x[i + 2] * hl[i + 2], l3 += x[i + 3] * hl[i + 3];
		r0 += x[i] * hr[i], r1 += x[i + 1] * hr[i + 1], r2 += x[i + 2] * hr[i + 2], r3 += x[i + 3] * hr[i + 3];
	}
	l = (l0 + l1) + (l2 + l3);
	r = (r0 + r1) + (r2 + r3);
#endif
}

/* Panners */

struct panner_state {
	struct params {
		double azimuth = 0.0, elevation = 0.0, distance = 0.0, gain = 1.0;
		distance_params distance_settings;
	};
	unsigned int sr;
	param_box<params> box;
	params p;
	bool first = true;
	std::atomic<bool> reset_pending{false};

	explicit panner_state(unsigned int sample_rate) : sr(std::max(1u, sample_rate)) {}
	virtual ~panner_state() {}
	double total_gain() const { return p.gain * distance_gain(p.distance_settings, p.distance); }
	virtual void update(bool snap) = 0;
	virtual void run(const float *input, float *output, unsigned int frames, bool accumulate) = 0;
	virtual void clear() = 0;
	void process(const float *input, float *output, unsigned int frames, bool accumulate) {
		if (!input || !output) return;
		denormal_guard guard;
		if (reset_pending.exchange(false)) clear();
		while (frames) {
			unsigned int n = std::min(frames, CHUNK);
			params np;
			if (box.poll(np)) {
				p = np;
				update(first);
			}
			first = false;
			run(input, output, n, accumulate);
			input += n, output += n * 2, frames -= n;
		}
	}
};

/* Synthizer's HrtfPanner. Each output sample is a convolution with the current HRIRs followed by a fractional ITD delay per ear. When the position changes the HRIRs and ITD crossfade over 64 samples (at 44100hz); a position change during a crossfade is picked up once it finishes. */
struct hrtf_state : panner_state {
	std::shared_ptr<const hrtf_dataset> data;
	unsigned int length, xfade_len, xfade_pos, fade_len, itd_mask, itd_pos = 0, cur = 0;
	// Input history followed by the current chunk, so that convolution always reads contiguous memory.
	std::vector<float> history;
	// [set][ear], stored reversed so that convolution walks the history and the impulse in the same direction.
	std::vector<float> impulses[2][2];
	std::vector<float> itd_lines[2];
	double cur_azimuth = 0.0, cur_elevation = 0.0;
	float itd_prev[2] = {0.0f, 0.0f}, itd_cur[2] = {0.0f, 0.0f};
	ramp gain;

	explicit hrtf_state(unsigned int sample_rate) : panner_state(sample_rate) {
		data = get_hrtf_dataset(sr);
		length = data->length;
		xfade_len = xfade_pos = scale_samples(sr, 64);
		fade_len = scale_samples(sr, 256);
		history.assign(length - 1 + CHUNK, 0.0f);
		for (auto &set : impulses)
			for (auto &ear : set) ear.assign(length, 0.0f);
		itd_mask = next_pow2((unsigned int)std::ceil(HRTF_MAX_ITD * sr / REFERENCE_SR) + 4) - 1;
		for (auto &line : itd_lines) line.assign(itd_mask + 1, 0.0f);
		update(true);
	}
	void load(unsigned int set) {
		cur_azimuth = p.azimuth, cur_elevation = p.elevation;
		compute_hrtf_impulses(*data, cur_azimuth, cur_elevation, impulses[set][0].data(), impulses[set][1].data());
		for (auto &ear : impulses[set]) std::reverse(ear.begin(), ear.end());
		auto itd = compute_itd(cur_azimuth, cur_elevation, sr);
		itd_cur[0] = float(itd.first), itd_cur[1] = float(itd.second);
	}
	void update(bool snap) override {
		if (snap) {
			load(cur);
			itd_prev[0] = itd_cur[0], itd_prev[1] = itd_cur[1];
			xfade_pos = xfade_len;
			gain.snap(float(total_gain()));
		} else gain.set(float(total_gain()), fade_len);
	}
	void clear() override {
		std::fill(history.begin(), history.end(), 0.0f);
		for (auto &line : itd_lines) std::fill(line.begin(), line.end(), 0.0f);
	}
	float read_itd(unsigned int ear, float delay) const {
		unsigned int i = (unsigned int)delay;
		float f = delay - i, a = itd_lines[ear][(itd_pos - i) & itd_mask], b = itd_lines[ear][(itd_pos - i - 1) & itd_mask];
		return a + (b - a) * f;
	}
	void run(const float *input, float *output, unsigned int frames, bool accumulate) override {
		if (xfade_pos >= xfade_len && (p.azimuth != cur_azimuth || p.elevation != cur_elevation)) {
			itd_prev[0] = itd_cur[0], itd_prev[1] = itd_cur[1];
			cur ^= 1;
			load(cur);
			xfade_pos = 0;
		}
		float *h = history.data();
		std::copy(input, input + frames, h + length - 1);
		const float *cl = impulses[cur][0].data(), *cr = impulses[cur][1].data(), *pl = impulses[cur ^ 1][0].data(), *pr = impulses[cur ^ 1][1].data();
		for (unsigned int i = 0; i < frames; i++) {
			float l, r, itd_l = itd_cur[0], itd_r = itd_cur[1];
			convolve_stereo(h + i, cl, cr, length, l, r);
			if (xfade_pos < xfade_len) {
				float ol, orr, w = float(xfade_pos++) / xfade_len;
				convolve_stereo(h + i, pl, pr, length, ol, orr);
				l = ol + (l - ol) * w, r = orr + (r - orr) * w;
				itd_l = itd_prev[0] + (itd_l - itd_prev[0]) * w, itd_r = itd_prev[1] + (itd_r - itd_prev[1]) * w;
			}
			itd_lines[0][itd_pos] = l, itd_lines[1][itd_pos] = r;
			float g = gain.next(), ol = read_itd(0, itd_l) * g, orr = read_itd(1, itd_r) * g;
			itd_pos = (itd_pos + 1) & itd_mask;
			float *o = output + i * 2;
			o[0] = accumulate ? o[0] + ol : ol;
			o[1] = accumulate ? o[1] + orr : orr;
		}
		std::memmove(h, h + frames, (length - 1) * sizeof(float));
	}
};

// Synthizer's StereoPanner, with gain changes ramped instead of jumping.
struct stereo_state : panner_state {
	ramp gain_l, gain_r;
	unsigned int fade_len;

	explicit stereo_state(unsigned int sample_rate) : panner_state(sample_rate), fade_len(scale_samples(sr, 256)) { update(true); }
	void update(bool snap) override {
		// Azimuth is clockwise from forward; the scalar wants clockwise from left, folding the back half onto the front.
		double angle = std::fmod(90.0 + p.azimuth, 360.0), g = total_gain();
		double scalar = angle <= 180.0 ? -1.0 + 2.0 * angle / 180.0 : 1.0 - 2.0 * (angle - 180.0) / 180.0;
		double pan = (1.0 + scalar) / 2.0 * PI / 2.0;
		float l = float(std::cos(pan) * g), r = float(std::sin(pan) * g);
		if (snap) gain_l.snap(l), gain_r.snap(r);
		else gain_l.set(l, fade_len), gain_r.set(r, fade_len);
	}
	void clear() override {}
	void run(const float *input, float *output, unsigned int frames, bool accumulate) override {
		for (unsigned int i = 0; i < frames; i++) {
			float *o = output + i * 2, l = input[i] * gain_l.next(), r = input[i] * gain_r.next();
			o[0] = accumulate ? o[0] + l : l;
			o[1] = accumulate ? o[1] + r : r;
		}
	}
};

/* FDN reverb.
 *
 * Synthizer's design: 8 delay lines whose lengths are primes spread around the mean free path, a 3 band equalizer on each feedback path setting per band decay from t60, random modulation of the line lengths, and an output taken from the lines after the late reflections delay (even lines left, odd lines right).
 *
 * Changes from Synthizer:
 * - The feedback matrix is an 8x8 Hadamard rather than a Householder reflection. An 8 line Householder matrix keeps 75% of each line on itself, so the lines behave like loosely coupled comb filters; Hadamard spreads every line equally into all others, building echo density much faster.
 * - The input passes through a 4 stage diffuser (delays, Hadamard mixing and polarity flips) whose length scales with the mean free path and diffusion, so the onset is a smear of early reflections instead of a single click.
 * - The equalizer had its shelf gains inverted (mid - band instead of band - mid) and applied rolloff to decay rate instead of decay time, so band t60s came out as t60 / (2 - rolloff) instead of the documented t60 * rolloff. With the defaults the highs rang for 2/3 of t60 instead of 1/2, and a rolloff of 2 never decayed at all.
 * - Line lengths account for the average modulation depth when computing decay, and are read with allpass rather than linear interpolation. Linear interpolation inside a feedback loop adds a time varying high frequency loss on every pass, so Synthizer's highs decayed faster than requested.
 * - Changes to line lengths and the late reflections delay glide instead of jumping, gains ramp, and freeze is new. */
struct fdn_reverb_state {
	static const unsigned int LINES = 8, STAGES = 4;
	static constexpr double MAX_MEAN_FREE_PATH = 0.5, MAX_MODULATION_DEPTH = 0.3, MAX_LATE_DELAY = 0.5, GLIDE_SECONDS = 0.5, DIFFUSER_SCALE = 0.5, MIN_DB = -150.0;
	static constexpr double DIFFUSER_WEIGHTS[STAGES] = {8.0 / 15.0, 4.0 / 15.0, 2.0 / 15.0, 1.0 / 15.0};

	struct params {
		double wet = 0.7, dry = 1.0, width = 1.0;
		bool freeze = false;
		double input_lowpass = 2000.0, input_highpass = 0.0;
		double mean_free_path = 0.1, t60 = 0.3, lf_rolloff = 1.0, lf_reference = 200.0, hf_rolloff = 0.5, hf_reference = 500.0, diffusion = 1.0;
		double modulation_depth = 0.01, modulation_frequency = 0.5, late_reflections_delay = 0.03;
	};

	unsigned int sr, channels;
	param_box<params> box;
	params p;
	bool first = true;
	std::atomic<bool> reset_pending{false};
	prime_table primes;
	unsigned int pos = 0, line_mask, max_base_delay;
	std::vector<float> lines;
	std::vector<float> diffusers[STAGES];
	unsigned int diffuser_masks[STAGES], diffuser_delays[STAGES][LINES];
	float diffuser_offsets[STAGES][LINES], diffuser_signs[STAGES][LINES];
	glide delays[LINES], late_delay, diffusion_time;
	random_sequence modulators[LINES];
	double applied_depth = -1.0, applied_frequency = -1.0;
	biquad_coefs low_shelves[LINES], high_shelves[LINES], lowpass, highpass;
	biquad_state low_states[LINES], high_states[LINES], lowpass_state, highpass_state;
	float allpass_states[LINES] = {};
	unsigned int diffuser_min = 0;
	bool lowpass_on = false, highpass_on = false;
	ramp wet, dry, width, freeze;

	fdn_reverb_state(unsigned int sample_rate, unsigned int channel_count) : sr(std::max(1u, sample_rate)), channels(std::max(1u, channel_count)), primes((unsigned int)std::ceil(2.0 * MAX_MEAN_FREE_PATH * std::max(1u, sample_rate)) + 1024) {
		unsigned int max_depth = (unsigned int)std::ceil(MAX_MODULATION_DEPTH * sr), frames = next_pow2((unsigned int)std::ceil((2.0 * MAX_MEAN_FREE_PATH + MAX_MODULATION_DEPTH) * sr) + 16);
		line_mask = frames - 1;
		max_base_delay = frames - max_depth - 8;
		lines.assign(frames * LINES, 0.0f);
		rng gen;
		for (unsigned int s = 0; s < STAGES; s++) {
			diffuser_masks[s] = next_pow2((unsigned int)std::ceil(DIFFUSER_SCALE * MAX_MEAN_FREE_PATH * DIFFUSER_WEIGHTS[s] * sr) + 2) - 1;
			diffusers[s].assign((diffuser_masks[s] + 1) * LINES, 0.0f);
			for (unsigned int j = 0; j < LINES; j++) {
				diffuser_offsets[s][j] = (j + (gen.next_float() + 1.0f) * 0.5f) / LINES;
				diffuser_signs[s][j] = gen.next_float() < 0.0f ? -1.0f : 1.0f;
			}
		}
		apply(true);
	}

	void update_diffuser_delays() {
		diffuser_min = 0;
		for (unsigned int s = 0; s < STAGES; s++) {
			for (unsigned int j = 0; j < LINES; j++) diffuser_delays[s][j] = std::min(diffuser_masks[s], (unsigned int)std::lround(diffuser_offsets[s][j] * DIFFUSER_WEIGHTS[s] * diffusion_time.value));
			diffuser_min += *std::min_element(diffuser_delays[s], diffuser_delays[s] + LINES);
		}
	}

	static double band_db(double mid_db, double rolloff) { return rolloff <= 0.0 ? MIN_DB : clamp(mid_db / rolloff, MIN_DB, 0.0); }

	void apply(bool snap) {
		const unsigned int fade = scale_samples(sr, 256), glide_len = (unsigned int)(GLIDE_SECONDS * sr);
		auto set_ramp = [&](ramp &r, double v) { snap ? r.snap(float(v)) : r.set(float(v), fade); };
		auto set_glide = [&](glide &g, double v) { snap ? g.snap(v) : g.set(v, glide_len); };
		set_ramp(wet, p.wet);
		set_ramp(dry, p.dry);
		set_ramp(width, p.width);
		set_ramp(freeze, p.freeze ? 1.0 : 0.0);
		const double nyquist = sr * 0.5;
		bool was_lowpass = lowpass_on, was_highpass = highpass_on;
		lowpass_on = p.input_lowpass > 0.0 && p.input_lowpass < nyquist;
		highpass_on = p.input_highpass > 0.0 && p.input_highpass < nyquist;
		if (lowpass_on) lowpass = design_biquad(biquad_type::lowpass, p.input_lowpass, 0.7071067811865476, 0.0, sr);
		if (highpass_on) highpass = design_biquad(biquad_type::highpass, p.input_highpass, 0.7071067811865476, 0.0, sr);
		if (lowpass_on && !was_lowpass) lowpass_state = biquad_state();
		if (highpass_on && !was_highpass) highpass_state = biquad_state();

		/* Synthizer's line lengths: the first 2 lines sit at the mean free path, and each following pair at mfp * f and mfp * (2 - f) with f shrinking as diffusion grows, so the average stays the mean free path. Primes keep the lines from sharing resonances, and sorting keeps each line's length moving smoothly when parameters change. */
		const double mfp = p.mean_free_path * sr;
		unsigned int targets[LINES];
		targets[0] = primes.closest((unsigned int)mfp, nullptr, 0);
		targets[1] = primes.closest((unsigned int)mfp, targets, 1);
		const double diffusion_base = 1.0 + 0.4 * p.diffusion;
		for (unsigned int i = 2; i < LINES; i += 2) {
			double fraction = 1.0 / std::pow(diffusion_base, i / 2 + 1);
			targets[i] = primes.closest((unsigned int)(mfp * fraction), targets, i);
			targets[i + 1] = primes.closest((unsigned int)(mfp * (2.0 - fraction)), targets, i + 1);
		}
		for (auto &t : targets) t = clamp(t, 2u, max_base_delay);
		std::sort(targets, targets + LINES);
		for (unsigned int i = 0; i < LINES; i++) set_glide(delays[i], targets[i]);

		const double depth = p.modulation_depth * sr;
		if (depth != applied_depth || p.modulation_frequency != applied_frequency) {
			// The step counts differ slightly per line so that the modulators don't all turn around on the same sample.
			for (unsigned int i = 0; i < LINES; i++) modulators[i].configure((unsigned int)(sr / p.modulation_frequency) + i, 0.0f, float(depth));
			applied_depth = depth, applied_frequency = p.modulation_frequency;
		}

		/* Decay: a sample travelling through t60 seconds of delay line should lose 60db, so each line attenuates by its length times the per sample decay. The mid band gain is folded into the low shelf; the shelves move the low and high bands from the mid gain to their own. */
		const double decay_per_sample = -60.0 / (p.t60 + 0.001) / sr;
		for (unsigned int i = 0; i < LINES; i++) {
			double mid = clamp((targets[i] + depth * 0.5) * decay_per_sample, MIN_DB, 0.0), low = band_db(mid, p.lf_rolloff), high = band_db(mid, p.hf_rolloff);
			low_shelves[i] = design_biquad(biquad_type::lowshelf, p.lf_reference, 0.7071067811865476, low - mid, sr);
			high_shelves[i] = design_biquad(biquad_type::highshelf, p.hf_reference, 0.7071067811865476, high - mid, sr);
			double g = db_to_gain(mid);
			low_shelves[i].b0 *= g, low_shelves[i].b1 *= g, low_shelves[i].b2 *= g;
		}

		set_glide(late_delay, p.late_reflections_delay * sr);
		set_glide(diffusion_time, DIFFUSER_SCALE * p.mean_free_path * p.diffusion * sr);
		update_diffuser_delays();
	}

	void clear() {
		std::fill(lines.begin(), lines.end(), 0.0f);
		for (auto &d : diffusers) std::fill(d.begin(), d.end(), 0.0f);
		for (unsigned int i = 0; i < LINES; i++) low_states[i] = high_states[i] = biquad_state(), allpass_states[i] = 0.0f;
		lowpass_state = highpass_state = biquad_state();
	}

	/* First order allpass interpolation. Unlike linear or cubic interpolation it has unity gain at every frequency, so it adds no extra high frequency loss inside the feedback loop and band t60s come out as requested. The fractional part is kept in [0.5, 1.5) where the allpass coefficient stays small and well behaved. delay must be at least 1.5. */
	float read_line(unsigned int lane, double delay) {
		unsigned int i = (unsigned int)(delay - 0.5);
		float f = float(delay - i), a = (1.0f - f) / (1.0f + f);
		float x0 = lines[((pos - i) & line_mask) * LINES + lane], x1 = lines[((pos - i - 1) & line_mask) * LINES + lane];
		return allpass_states[lane] = a * x0 + x1 - a * allpass_states[lane];
	}

	double tail_length() const {
		params q = box.read();
		if (q.freeze) return std::numeric_limits<double>::infinity();
		return q.t60 * std::max({1.0, q.lf_rolloff, q.hf_rolloff}) + q.late_reflections_delay + q.mean_free_path * (2.0 + DIFFUSER_SCALE);
	}

	void process(const float *input, float *output, unsigned int frames, bool accumulate) {
		if (!input || !output) return;
		denormal_guard guard;
		if (reset_pending.exchange(false)) clear();
		const float inv_channels = 1.0f / channels;
		for (unsigned int f = 0; f < frames; f++, input += channels, output += channels) {
			params np;
			if (f % CHUNK == 0 && box.poll(np)) {
				p = np;
				apply(first);
			}
			first = false;
			float sum = 0.0f;
			for (unsigned int c = 0; c < channels; c++) sum += input[c];
			double x = sum * inv_channels;
			if (lowpass_on) x = lowpass_state.tick(lowpass, x);
			if (highpass_on) x = highpass_state.tick(highpass, x);
			const float frozen = freeze.next();
			float v[LINES], r[LINES];
			std::fill(v, v + LINES, float(x) * (1.0f - frozen) * (1.0f / LINES));
			if (diffusion_time.active()) {
				diffusion_time.next();
				update_diffuser_delays();
			}
			for (unsigned int s = 0; s < STAGES; s++) {
				float *buf = diffusers[s].data();
				const unsigned int mask = diffuser_masks[s];
				std::copy(v, v + LINES, buf + (pos & mask) * LINES);
				for (unsigned int j = 0; j < LINES; j++) v[j] = buf[((pos - diffuser_delays[s][j]) & mask) * LINES + j] * diffuser_signs[s][j];
				hadamard8(v);
			}
			for (unsigned int j = 0; j < LINES; j++) r[j] = read_line(j, std::max(1.5, delays[j].next() + modulators[j].tick()));
			// The equalizer keeps running while frozen so that unfreezing doesn't start it from stale state.
			for (unsigned int j = 0; j < LINES; j++) {
				float e = float(high_states[j].tick(high_shelves[j], low_states[j].tick(low_shelves[j], r[j])));
				r[j] = e + (r[j] - e) * frozen;
			}
			hadamard8(r);
			float *frame = &lines[(pos & line_mask) * LINES];
			for (unsigned int j = 0; j < LINES; j++) frame[j] = r[j] + v[j];
			// The diffuser's shortest path already delays the onset, so take it off the output tap to keep late_reflections_delay exact.
			const double ld = std::max(0.0, late_delay.next() - diffuser_min);
			const unsigned int li = (unsigned int)ld;
			const float lf = float(ld - li), *a = &lines[((pos - li) & line_mask) * LINES], *b = &lines[((pos - li - 1) & line_mask) * LINES];
			float l = (a[0] + a[2] + a[4] + a[6]) * (1.0f - lf) + (b[0] + b[2] + b[4] + b[6]) * lf;
			float rr = (a[1] + a[3] + a[5] + a[7]) * (1.0f - lf) + (b[1] + b[3] + b[5] + b[7]) * lf;
			const float mid = (l + rr) * 0.5f, side = (l - rr) * 0.5f * width.next(), g = wet.next();
			write_stereo(input, output, channels, (mid + side) * g, (mid - side) * g, dry.next(), accumulate);
			pos++;
		}
	}
};

/* Synthizer's GlobalEcho. Synthizer faded the whole output in from silence over a block whenever the taps changed; this crossfades from the old taps to the new ones instead. */
struct echo_state {
	struct tap {
		unsigned int delay;
		float gain_l, gain_r;
	};
	struct params {
		double wet = 1.0, dry = 1.0;
	};

	unsigned int sr, channels, max_delay, mask, pos = 0, xfade_len, xfade_pos, fade_len;
	std::vector<float> line;
	param_box<params> box;
	bool first = true;
	std::atomic<bool> reset_pending{false};
	// Setters fill staging (allocating on their own thread) and the audio thread swaps it in, so no allocation happens while processing.
	mutable std::mutex taps_mutex;
	std::vector<echo_tap> taps_public;
	std::vector<tap> staging, active, previous;
	std::atomic<bool> taps_dirty{false};
	ramp wet, dry;

	echo_state(unsigned int sample_rate, unsigned int channel_count, double max_delay_seconds) : sr(std::max(1u, sample_rate)), channels(std::max(1u, channel_count)) {
		max_delay = (unsigned int)std::ceil(sanitize(max_delay_seconds, 0.0, 3600.0) * sr);
		mask = next_pow2(max_delay + 1) - 1;
		line.assign((mask + 1) * 2, 0.0f);
		xfade_len = xfade_pos = fade_len = scale_samples(sr, 256);
		params defaults;
		wet.snap(float(defaults.wet));
		dry.snap(float(defaults.dry));
	}

	void set_taps(const std::vector<echo_tap> &taps) {
		std::lock_guard<std::mutex> lock(taps_mutex);
		taps_public = taps;
		staging.clear();
		for (auto &t : taps) staging.push_back({(unsigned int)std::lround(sanitize(t.delay, 0.0, double(max_delay) / sr) * sr), float(t.gain_l), float(t.gain_r)});
		taps_dirty.store(true, std::memory_order_release);
	}

	void poll_taps() {
		if (xfade_pos < xfade_len || !taps_dirty.load(std::memory_order_acquire)) return;
		std::unique_lock<std::mutex> lock(taps_mutex, std::try_to_lock);
		if (!lock.owns_lock()) return;
		std::swap(previous, active);
		std::swap(active, staging);
		taps_dirty.store(false, std::memory_order_relaxed);
		xfade_pos = first ? xfade_len : 0;
	}

	double tail_length() const {
		std::lock_guard<std::mutex> lock(taps_mutex);
		double m = 0.0;
		for (auto &t : taps_public) m = std::max(m, sanitize(t.delay, 0.0, double(max_delay) / sr));
		return m;
	}

	void sum_taps(const std::vector<tap> &taps, float &l, float &r) const {
		l = r = 0.0f;
		for (auto &t : taps) {
			const float *s = &line[((pos - t.delay) & mask) * 2];
			l += s[0] * t.gain_l, r += s[1] * t.gain_r;
		}
	}

	void process(const float *input, float *output, unsigned int frames, bool accumulate) {
		if (!input || !output) return;
		if (reset_pending.exchange(false)) std::fill(line.begin(), line.end(), 0.0f);
		params np;
		if (box.poll(np)) {
			first ? wet.snap(float(np.wet)) : wet.set(float(np.wet), fade_len);
			first ? dry.snap(float(np.dry)) : dry.set(float(np.dry), fade_len);
		}
		while (frames) {
			unsigned int n = std::min(frames, CHUNK);
			poll_taps();
			first = false;
			for (unsigned int i = 0; i < n; i++, input += channels, output += channels) {
				float *w = &line[(pos & mask) * 2], l, r;
				read_stereo(input, channels, w[0], w[1]);
				sum_taps(active, l, r);
				if (xfade_pos < xfade_len) {
					float ol, orr, t = float(xfade_pos++) / xfade_len;
					sum_taps(previous, ol, orr);
					l = ol + (l - ol) * t, r = orr + (r - orr) * t;
				}
				const float g = wet.next();
				write_stereo(input, output, channels, l * g, r * g, dry.next(), accumulate);
				pos++;
			}
			frames -= n;
		}
	}
};

/* Synthizer's BiquadFilter: reconfiguring crossfades from the old filter to the new one over 256 samples (at 44100hz). The new filter starts from a copy of the old one's state rather than from silence, which avoids a startup transient. */
struct biquad_filter_state {
	struct params {
		biquad_type type = biquad_type::none;
		double frequency = 1000.0, q = 0.7071067811865476, gain_db = 0.0;
	};

	unsigned int sr, channels, active = 0, xfade_len, xfade_pos;
	param_box<params> box;
	bool first = true;
	std::atomic<bool> reset_pending{false};
	biquad_coefs coefs[2];
	std::vector<biquad_state> states[2];

	biquad_filter_state(unsigned int sample_rate, unsigned int channel_count) : sr(std::max(1u, sample_rate)), channels(std::max(1u, channel_count)) {
		xfade_len = xfade_pos = scale_samples(sr, 256);
		for (auto &s : states) s.assign(channels, biquad_state());
	}

	void process(const float *input, float *output, unsigned int frames, bool accumulate) {
		if (!input || !output) return;
		denormal_guard guard;
		if (reset_pending.exchange(false))
			for (auto &s : states) std::fill(s.begin(), s.end(), biquad_state());
		while (frames) {
			unsigned int n = std::min(frames, CHUNK);
			params np;
			if (xfade_pos >= xfade_len && box.poll(np)) {
				biquad_coefs c = design_biquad(np.type, np.frequency, np.q, np.gain_db, sr);
				if (first) coefs[active] = c;
				else {
					coefs[active ^ 1] = c;
					std::copy(states[active].begin(), states[active].end(), states[active ^ 1].begin());
					xfade_pos = 0;
				}
			}
			first = false;
			for (unsigned int i = 0; i < n; i++, input += channels, output += channels) {
				const bool fading = xfade_pos < xfade_len;
				const float w = fading ? float(xfade_pos++) / xfade_len : 0.0f;
				for (unsigned int c = 0; c < channels; c++) {
					float x = input[c], y = float(states[active][c].tick(coefs[active], x));
					if (fading) y += (float(states[active ^ 1][c].tick(coefs[active ^ 1], x)) - y) * w;
					output[c] = accumulate ? output[c] + y : y;
				}
				if (fading && xfade_pos == xfade_len) active ^= 1;
			}
			frames -= n;
		}
	}
};

