double distance_gain(const distance_params &params, double distance) {
	double mul = 1.0;
	const double d = std::max(0.0, distance);
	switch (params.model) {
	case distance_model::linear:
		if (params.max > params.ref) mul = 1.0 - params.rolloff * (detail::clamp(d, params.ref, params.max) - params.ref) / (params.max - params.ref);
		else mul = d > params.ref ? 1.0 - params.rolloff : 1.0;
		break;
	case distance_model::exponential:
		mul = params.ref <= 0.0 ? 0.0 : std::pow(std::max(d, params.ref) / params.ref, -params.rolloff);
		break;
	case distance_model::inverse:
		mul = params.ref <= 0.0 ? 0.0 : params.ref / (params.ref + params.rolloff * (std::max(d, params.ref) - params.ref));
		break;
	default:
		break;
	}
	// Counterintuitively this cuts everything further than the boost distance, so that nothing closer can go above unity.
	if (d > params.closeness_boost_distance) mul *= detail::db_to_gain(-params.closeness_boost);
	return std::isnan(mul) ? 0.0 : detail::clamp(mul, 0.0, 1.0);
}

spherical_position world_to_spherical(const vec3 &source, const vec3 &listener, const vec3 &listener_at, const vec3 &listener_up) {
	auto dot = [](const vec3 &a, const vec3 &b) { return a.x * b.x + a.y * b.y + a.z * b.z; };
	auto cross = [](const vec3 &a, const vec3 &b) { return vec3{a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x}; };
	auto normalize = [&](const vec3 &a) {
		double m = std::sqrt(dot(a, a));
		return m > 0.0 ? vec3{a.x / m, a.y / m, a.z / m} : vec3();
	};
	spherical_position out;
	const vec3 pos{source.x - listener.x, source.y - listener.y, source.z - listener.z}, at = normalize(listener_at), right = normalize(cross(listener_at, listener_up)), up = cross(right, at);
	out.distance = std::sqrt(dot(pos, pos));
	// A source at the center of the head, or a degenerate orientation, is treated as straight ahead.
	if (out.distance == 0.0 || dot(right, right) == 0.0) return out;
	double x = dot(right, pos) / out.distance, y = dot(at, pos) / out.distance, z = dot(up, pos) / out.distance;
	out.azimuth = detail::clamp(std::fmod(std::atan2(x, y) * 180.0 / detail::PI + 360.0, 360.0), 0.0, 360.0);
	out.elevation = detail::clamp(std::atan2(z, std::sqrt(x * x + y * y)) * 180.0 / detail::PI, -90.0, 90.0);
	return out;
}

