void panner_effect::set_angles(double azimuth, double elevation) {
	state->box.write([&](detail::panner_state::params &p) {
		p.azimuth = detail::wrap_azimuth(azimuth);
		p.elevation = detail::sanitize(elevation, -90.0, 90.0);
	});
}
void panner_effect::set_azimuth(double azimuth) {
	state->box.write([&](detail::panner_state::params &p) { p.azimuth = detail::wrap_azimuth(azimuth); });
}
double panner_effect::get_azimuth() const { return state->box.read().azimuth; }
void panner_effect::set_elevation(double elevation) {
	state->box.write([&](detail::panner_state::params &p) { p.elevation = detail::sanitize(elevation, -90.0, 90.0); });
}
double panner_effect::get_elevation() const { return state->box.read().elevation; }
void panner_effect::set_panning_scalar(double scalar) {
	scalar = detail::sanitize(scalar, -1.0, 1.0);
	set_angles(scalar >= 0.0 ? 90.0 * scalar : 360.0 + 90.0 * scalar, 0.0);
}
void panner_effect::set_position(const vec3 &position) {
	spherical_position s = world_to_spherical(position);
	state->box.write([&](detail::panner_state::params &p) {
		p.azimuth = s.azimuth, p.elevation = s.elevation;
		p.distance = std::isfinite(s.distance) ? s.distance : 0.0;
	});
}
void panner_effect::set_distance(double distance) {
	state->box.write([&](detail::panner_state::params &p) { p.distance = detail::sanitize(distance, 0.0, std::numeric_limits<double>::max()); });
}
